#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_4.md ]] || { echo 'Run in the repository root after the fourth Android visual-alignment update.' >&2; exit 1; }
python3 - <<'VISUAL_GROUP_FIVE'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/discover/discover_screen.dart': '',
'desktop/hyper_player/lib/discover/android_details.dart': '',
'desktop/hyper_player/test/details_visual_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_5.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Android-style movie/series details and season/episode browsing installed. Android unchanged.')
VISUAL_GROUP_FIVE
